// 画像データ（Base64埋め込み）
const IMG_GIRL_CLOSED = "data:image/png;base64,";
const IMG_GIRL_OPEN = "data:image/png;base64,";
const IMG_BG = "data:image/png;base64,";
const IMG_APPLE = "data:image/png;base64,";
const IMG_BREAD = "data:image/png;base64,";
const IMG_PEPPER = "data:image/png;base64,";
const IMG_PUDDING = "data:image/png;base64,";
const IMG_PUMPKIN = "data:image/png;base64,";

// ===== 定数 =====
const CANVAS_W = 600;
const CANVAS_H = 500;
const GIRL_W = 180;
const GIRL_H = 180;
const GIRL_SPEED = 380;
const ITEM_SIZE = 150;
const MOUTH_OPEN_DIST = 200;

// アイテム定義（base64データを使用）
const ITEM_DEFS_RAW = [
  { src: IMG_PUDDING,  type: 'sweet',  label: 'プリン'   },
  { src: IMG_APPLE,    type: 'sweet',  label: 'いちご'   },
  { src: IMG_BREAD,    type: 'sweet',  label: 'ドーナツ' },
  { src: IMG_PEPPER,   type: 'veggie', label: 'ピーマン' },
  { src: IMG_PUMPKIN,  type: 'veggie', label: 'かぼちゃ' },
];

// ===== 画像読み込み =====
function loadImage(src) {
  return new Promise((res) => {
    const img = new Image();
    img.onload = () => res(img);
    img.onerror = () => res(null);
    img.src = src;
  });
}

// ===== ゲームクラス =====
class FoodCatcherGame {
  constructor() {
    this.canvas = document.getElementById('game');
    this.ctx = this.canvas.getContext('2d');
    this.scoreEl = document.getElementById('score');
    this.livesEl = document.getElementById('lives');
    this.images = {};
    this.itemDefs = [];
    this.keys = { left: false, right: false };
    this.bindInput();
    this.reset();
  }

  reset() {
    this.score = 0;
    this.lives = 3;
    this.items = [];
    this.spawnTimer = 0;
    this.spawnInterval = 1.4;
    this.running = false;
    this.girl = { x: CANVAS_W / 2 - GIRL_W / 2, y: CANVAS_H - GIRL_H - 10 };
    this.mouthOpen = false;
    this.popEffects = [];
  }

  async loadAssets() {
    this.images.bg         = await loadImage(IMG_BG);
    this.images.girlClosed = await loadImage(IMG_GIRL_CLOSED);
    this.images.girlOpen   = await loadImage(IMG_GIRL_OPEN);
    for (const def of ITEM_DEFS_RAW) {
      const img = await loadImage(def.src);
      this.itemDefs.push({ ...def, img });
    }
  }

  bindInput() {
    window.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft')  { this.keys.left  = true;  e.preventDefault(); }
      if (e.key === 'ArrowRight') { this.keys.right = true;  e.preventDefault(); }
    });
    window.addEventListener('keyup', (e) => {
      if (e.key === 'ArrowLeft')  this.keys.left  = false;
      if (e.key === 'ArrowRight') this.keys.right = false;
    });
    window.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      const x = touch.clientX;
      if (x < window.innerWidth / 2) this.keys.left = true;
      else this.keys.right = true;
    }, { passive: false });
    window.addEventListener('touchend', (e) => {
      e.preventDefault();
      this.keys.left = false;
      this.keys.right = false;
    }, { passive: false });
    window.addEventListener('touchmove', (e) => {
      e.preventDefault();
      const touch = e.touches[0];
      const x = touch.clientX;
      this.keys.left  = x < window.innerWidth / 2;
      this.keys.right = x >= window.innerWidth / 2;
    }, { passive: false });
  }

  spawnItem() {
    const def = this.itemDefs[Math.floor(Math.random() * this.itemDefs.length)];
    this.items.push({
      x: Math.random() * (CANVAS_W - ITEM_SIZE),
      y: -ITEM_SIZE,
      w: ITEM_SIZE, h: ITEM_SIZE,
      vy: 130 + Math.random() * 90 + this.score * 0.02,
      def,
    });
  }

  intersects(a, b) {
    return !(a.x+a.w < b.x || a.x > b.x+b.w || a.y+a.h < b.y || a.y > b.y+b.h);
  }

  nearestItemDist() {
    let minDist = Infinity;
    const cx = this.girl.x + GIRL_W / 2;
    const top = this.girl.y;
    for (const it of this.items) {
      const dx = cx - (it.x + it.w / 2);
      const dy = Math.max(0, top - (it.y + it.h));
      const d = Math.sqrt(dx*dx + dy*dy);
      if (d < minDist) minDist = d;
    }
    return minDist;
  }

  update(dt) {
    const dir = (this.keys.right?1:0) - (this.keys.left?1:0);
    this.girl.x = Math.max(0, Math.min(CANVAS_W - GIRL_W,
      this.girl.x + dir * GIRL_SPEED * dt));

    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      this.spawnItem();
      this.spawnTimer = this.spawnInterval * (0.7 + Math.random() * 0.6);
      this.spawnInterval = Math.max(0.55, this.spawnInterval - 0.005);
    }

    this.mouthOpen = this.nearestItemDist() < MOUTH_OPEN_DIST;

    const gr = { x: this.girl.x + GIRL_W*0.4, y: this.girl.y + GIRL_H*0.78, w: GIRL_W*0.2, h: GIRL_H*0.12 };
    for (let i = this.items.length-1; i >= 0; i--) {
      const it = this.items[i];
      it.y += it.vy * dt;
      if (it.y > CANVAS_H) { this.items.splice(i,1); continue; }
      if (this.intersects(gr, it)) {
        if (it.def.type === 'veggie') {
          this.lives--;
          this.addPop(it.x + it.w/2, it.y, '野菜！ライフ-1', '#e53935');
        } else {
          this.score += 10;
          this.addPop(it.x + it.w/2, it.y, '+10点', '#e91e8c');
        }
        this.items.splice(i, 1);
        if (this.lives <= 0) {
          this.running = false;
          setTimeout(() => this.showGameOver(), 500);
        }
      }
    }

    for (let i = this.popEffects.length-1; i >= 0; i--) {
      const p = this.popEffects[i];
      p.life -= dt; p.y -= 55*dt;
      if (p.life <= 0) this.popEffects.splice(i,1);
    }

    this.scoreEl.textContent = this.score;
    this.livesEl.textContent = '❤️'.repeat(Math.max(0, this.lives));
  }

  addPop(x, y, text, color) {
    this.popEffects.push({ x, y, text, color, life: 0.85 });
  }

  render() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);

    if (this.images.bg) {
      ctx.drawImage(this.images.bg, 0, 0, CANVAS_W, CANVAS_H);
    } else {
      ctx.fillStyle = '#fce4ec';
      ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);
    }

    for (const it of this.items) {
      if (it.def.img) {
        ctx.drawImage(it.def.img, it.x, it.y, it.w, it.h);
      } else {
        ctx.fillStyle = it.def.type === 'sweet' ? '#f06292' : '#66bb6a';
        ctx.fillRect(it.x, it.y, it.w, it.h);
      }
    }

    const girlImg = this.mouthOpen ? this.images.girlOpen : this.images.girlClosed;
    if (girlImg) ctx.drawImage(girlImg, this.girl.x, this.girl.y, GIRL_W, GIRL_H);

    for (const pop of this.popEffects) {
      ctx.save();
      ctx.globalAlpha = Math.min(1, pop.life / 0.4);
      ctx.font = 'bold 22px "Kaisei Decol", serif';
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 4; ctx.textAlign = 'center';
      ctx.strokeText(pop.text, pop.x, pop.y);
      ctx.fillStyle = pop.color;
      ctx.fillText(pop.text, pop.x, pop.y);
      ctx.restore();
    }
  }

  showGameOver() {
    document.getElementById('final-score').textContent = this.score;
    showScreen('gameover');
  }

  start() {
    this.reset();
    this.running = true;
    let last = performance.now();
    const loop = (now) => {
      const dt = Math.min((now-last)/1000, 0.05); last = now;
      if (this.running) { this.update(dt); this.render(); requestAnimationFrame(loop); }
      else { this.render(); }
    };
    requestAnimationFrame(loop);
  }
}

function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('screen-'+id).classList.add('active');
}

let game;
async function init() {
  game = new FoodCatcherGame();
  await game.loadAssets();

  function startGame(e) {
    e.preventDefault();
    e.stopPropagation();
    showScreen('game');
    game.start();
  }

  const btnStart = document.getElementById('btn-start');
  const btnRetry = document.getElementById('btn-retry');

  btnStart.addEventListener('click', startGame);
  btnStart.addEventListener('touchstart', startGame, { passive: false });
  btnRetry.addEventListener('click', startGame);
  btnRetry.addEventListener('touchstart', startGame, { passive: false });
}
init();
